   "register": "tu",
   "anker": "korrigieren",
   "notiz": "Lehrer + Zimmer ; im = in dem (datif, lieu où l'on est). jemand = quelqu'un ; niemand = personne. Le verbe toujours en deuxième position : Im Lehrerzimmer korrigiert …",
