   "anker": "haben",
   "notiz": "der Kloß = la boulette, la quenelle (plat !) – « avoir une boulette dans la gorge » = avoir la gorge serrée. im Hals = in dem Hals. sie ist gegangen = parfait avec sein (gehen).",
